#include <cstdio>
#include <algorithm>
#include <vector>
#define LL pair<long long, long long>
using namespace std;

long long C[62][62], A[32][32], B[32][32], totalComb;
int R, Cc, n;
char p[110];
long long CC[32][32], maxDiff;
vector<LL> P[32][2], Q[32][2];

void addPath(int x, int y, long long g, long long c1, long long c2, int ck) {
    if (x + y == R + n) {
        P[x][ck].push_back({g, c1});
        if (c2) Q[x][ck].push_back({g, c2});
        return;
    }
    addPath(x + 1, y, g + (!ck ? A[x + 1][y] : 0), c1, (p[x + y] != 'B' ? c2 : 0), ck);
    addPath(x, y + 1, g + (ck ? B[x][y + 1] : 0), c1, (p[x + y] != 'A' ? c2 : 0), ck);
}

void calcMin(int x, int y, long long g, int ck) {
    if (x + y == R + n) {
        if (P[x][ck].empty()) return;
        int t = lower_bound(P[x][ck].begin(), P[x][ck].end(), LL((totalComb + 1) / 2 - g, 0)) - P[x][ck].begin();
        if (t != P[x][ck].size() && P[x][ck][t].second > 0) {
            long long tp = (P[x][ck][t].first + g) * 2 - totalComb;
            if (tp < 0) tp = -tp;
            if (maxDiff > tp) maxDiff = tp;
        }
        if (t && P[x][ck][t - 1].second > 0) {
            long long tp = (P[x][ck][t - 1].first + g) * 2 - totalComb;
            if (tp < 0) tp = -tp;
            if (maxDiff > tp) maxDiff = tp;
        }
        return;
    }
    calcMin(x - 1, y, g + (!ck ? A[x][y] : 0), ck);
    calcMin(x, y - 1, g + (ck ? B[x][y] : 0), ck);
}

long long totalRes;

void calcMax(int x, int y, long long g, int ck) {
    if (x + y == R + n) {
        int t = lower_bound(Q[x][ck].begin(), Q[x][ck].end(), LL((totalComb + 1) / 2 - g, 0)) - Q[x][ck].begin();
        if (t != Q[x][ck].size() && Q[x][ck][t].second > 0) {
            long long tp = (Q[x][ck][t].first + g) * 2 - totalComb;
            if (tp < 0) tp = -tp;
            if (maxDiff == tp) {
                totalRes += Q[x][ck][t].second;
            }
        }
        if (t && Q[x][ck][t - 1].second > 0) {
            long long tp = (Q[x][ck][t - 1].first + g) * 2 - totalComb;
            if (tp < 0) tp = -tp;
            if (maxDiff == tp) {
                totalRes += Q[x][ck][t - 1].second;
            }
        }
        return;
    }
    if (p[x + y - 1] != 'B') calcMax(x - 1, y, g + (!ck ? A[x][y] : 0), ck);
    if (p[x + y - 1] != 'A') calcMax(x, y - 1, g + (ck ? B[x][y] : 0), ck);
}

void compress(vector<LL>& P) {
    if (P.empty()) return;
    sort(P.begin(), P.end());
    int cnt = 0;
    long long sum = 0;
    for (size_t i = 0; i < P.size(); i++) {
        sum += P[i];
        if (i == P.size() - 1 || P[i] != P[i + 1]) {
            P[cnt++] = P[i];
            sum = 0;
        }
    }
    P.resize(cnt);
}

int main() {
    int i, j;
    scanf("%d%d", &R, &Cc);
    scanf("%s", p);
    for (i = 0; i <= 60; i++) {
        C[i][0] = 1;
        for (j = 1; j <= i; j++) C[i][j] = C[i - 1][j - 1] + C[i - 1][j];
    }
    n = R + Cc;
    totalComb = C[n * 2][R * 2];
    for (i = 0; i <= n; i++) {
        for (j = 0; j <= n; j++) {
            if (i) A[i][j] = C[i - 1][R - 1] * (C[n * 2 - i][R] - C[j][R]);
            if (j) B[i][j] = C[j - 1][R - 1] * (C[n * 2 - j][R] - C[i][R]);
        }
    }
    memset(CC, 0, sizeof(CC));
    CC[0][0] = 1;
    for (i = 0; i <= n; i++) {
        for (j = 0; j <= n; j++) {
            if (i != n && p[i + j] != 'B') CC[i + 1][j] += CC[i][j];
            if (j != n && p[i + j] != 'A') CC[i][j + 1] += CC[i][j];
        }
    }
    for (i = R; i <= n; i++) {
        if (p[i + R - 1] != 'B') addPath(R, i, A[R][i], C[i + R - 1][R - 1], CC[R - 1][i], 0);
        if (p[i + R - 1] != 'A') addPath(i, R, B[i][R], C[i + R - 1][R - 1], CC[i][R - 1], 1);
    }
    for (i = R; i <= n; i++) {
        for (j = 0; j < 2; j++) {
            compress(P[i][j]);
            compress(Q[i][j]);
        }
    }
    maxDiff = totalComb + 1;
    calcMin(n, n, 0, 0);
    calcMin(n, n, 0, 1);
    calcMax(n, n, 0, 0);
    calcMax(n, n, 0, 1);
    printf("%lld\n", Result);
}
